# 13_data_factions.py -- the Thallen March's factions (owner-block "13" of data/factions.yaml), each conforming
# to 11.3.1: tier 0-5 with hold; ratings force/cunning/wealth/sway each 0..tier+2 summing to 4 + 2 x tier;
# temperament; goal clock by scope (local 8 / regional 12 / realm 12+12; petty 6); linchpins with SEALED
# pre-declared fates; values; patron deeds; ranks; duties; fields; boon; relations; seat and holds.
# Also the org-tie -> faction mapping for 02.9.5's faction ties (PR-11-4 consumes it).
# Read by 13-gen_region.py (which fills the template-default fields, validates and writes).

def fx(eid, **params):
    return {"effect_id": eid, "params": params}

def hold(f, s):
    return fx("eff.11.hold_step", faction=f, steps=s)

def stage(f, s):
    return fx("eff.11.stage_set", faction=f, stage=s)

def sit(t, region="loc.thallen", **roles):
    return fx("eff.11.new_situation", template=t, region=region, roles=roles)

def fact(subj, pred, val):
    return fx("eff.write_fact", subject=subj, predicate=pred, value=val)

def rel(f, toward, s):
    return fx("eff.11.relation_step", faction=f, toward=toward, steps=s)

def hook(text, source, entities, delivery="rumor"):
    return fx("eff.11.seed_hook", text=text, source=source, entities=entities, delivery=delivery)

def tick(clock, n):
    return fx("eff.tick_clock", clock=clock, ticks=n)

